import{_ as e,o as s,c as t,a2 as l}from"./chunks/framework.C2TvIV46.js";const g=JSON.parse('{"title":"Variable model","description":"","frontmatter":{},"headers":[],"relativePath":"language/variable-model.md","filePath":"language/variable-model.md"}'),n={name:"language/variable-model.md"};function o(p,a,c,r,d,i){return s(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="variable-model" tabindex="-1">Variable model <a class="header-anchor" href="#variable-model" aria-label="Permalink to &quot;Variable model&quot;">​</a></h1><p>Megalo variables hold typed values used by conditions and actions. They come in several varieties: custom variables you declare, built-in read-only engine state, and member variables attached to players, teams, and objects.</p><h2 id="custom-variables" tabindex="-1">Custom variables <a class="header-anchor" href="#custom-variables" aria-label="Permalink to &quot;Custom variables&quot;">​</a></h2><p>Custom variables are declared in <code>variables</code> blocks at the top level of a script.</p><h3 id="declaration-syntax" tabindex="-1">Declaration syntax <a class="header-anchor" href="#declaration-syntax" aria-label="Permalink to &quot;Declaration syntax&quot;">​</a></h3><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-keyword">global</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">special_death_type</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>Each entry line has four parts (scope is on the <code>variables</code> line itself):</p><table tabindex="0"><thead><tr><th>Part</th><th>Values</th></tr></thead><tbody><tr><td><strong>Scope</strong></td><td><code>global</code>, <code>player</code>, <code>team</code>, <code>object</code></td></tr><tr><td><strong>Network state</strong></td><td><code>local</code>, <code>networked</code>, <code>networked_high</code></td></tr><tr><td><strong>Type</strong></td><td><code>number</code>, <code>timer</code>, <code>object</code>, <code>team</code>, <code>player</code></td></tr><tr><td><strong>Initial value</strong></td><td>A literal or constant matching the type</td></tr></tbody></table><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-keyword">global</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">player</span><span class="megalo-text"> </span><span class="megalo-variable">killing_player</span><span class="megalo-text"> </span><span class="megalo-variable">none</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">special_death_type</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-type">player</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">is_leader</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">networked</span><span class="megalo-text"> </span><span class="megalo-type">timer</span><span class="megalo-text"> </span><span class="megalo-variable">game_start_vo</span><span class="megalo-text"> </span><span class="megalo-number">5</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">networked</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">heard_game_start</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">networked</span><span class="megalo-text"> </span><span class="megalo-type">object</span><span class="megalo-text"> </span><span class="megalo-variable">body</span><span class="megalo-text"> </span><span class="megalo-variable">none</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-type">object</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">networked</span><span class="megalo-text"> </span><span class="megalo-type">timer</span><span class="megalo-text"> </span><span class="megalo-variable">lifetime</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-type">team</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">networked</span><span class="megalo-text"> </span><span class="megalo-type">object</span><span class="megalo-text"> </span><span class="megalo-variable">goal</span><span class="megalo-text"> </span><span class="megalo-variable">none</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">networked</span><span class="megalo-text"> </span><span class="megalo-type">timer</span><span class="megalo-text"> </span><span class="megalo-variable">vehicle_refresh</span><span class="megalo-text"> </span><span class="megalo-number">30</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>The scope keyword appears on the <code>variables</code> line itself (<code>variables global</code>, <code>variables player</code>, etc.).</p><h3 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h3><p>Custom variable slot counts are listed under <strong>Limits</strong> on each <a href="/MegaloEvolved/beta/docs/versions/">megalo version page</a> — for example <a href="/MegaloEvolved/beta/docs/versions/49/#limits">49</a>, <a href="/MegaloEvolved/beta/docs/versions/73/#limits">73</a>, <a href="/MegaloEvolved/beta/docs/versions/107/#limits">107</a>, or <a href="/MegaloEvolved/beta/docs/versions/107-mcc/#limits">107 (MCC)</a>. Exceeding a cap fails the compile.</p><p>On MCC Reach, <a href="/MegaloEvolved/beta/docs/language/elements/trigger#action-scope"><code>temporary</code></a> variables may spill into unused global slots when overflow is enabled — see <a href="/MegaloEvolved/beta/docs/versions/107-mcc/#limits">107 (MCC) — Limits</a> and <a href="/MegaloEvolved/beta/docs/language/compiler-settings#temporary-variable-overflow">Compiler settings</a>.</p><h3 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Holds</th><th>Example initial value</th></tr></thead><tbody><tr><td><code>number</code></td><td>Integer</td><td><code>0</code>, <code>25</code>, <code>k_hidden_slayer</code></td></tr><tr><td><code>timer</code></td><td>Countdown timer</td><td><code>5</code>, <code>flag_return_time</code></td></tr><tr><td><code>object</code></td><td>Map object reference</td><td><code>none</code></td></tr><tr><td><code>team</code></td><td>Team reference</td><td><code>none</code>, <code>attackers</code></td></tr><tr><td><code>player</code></td><td>Player reference</td><td><code>none</code></td></tr></tbody></table><p>Megalo is type-safe: a variable&#39;s declared type is checked when it is used as an argument. Mismatched types produce a compile-time error.</p><h3 id="network-state" tabindex="-1">Network state <a class="header-anchor" href="#network-state" aria-label="Permalink to &quot;Network state&quot;">​</a></h3><table tabindex="0"><thead><tr><th>State</th><th>Behavior</th></tr></thead><tbody><tr><td><code>local</code></td><td>Not synchronized over the network. Reset to its initial value at the start of every tick to prevent misuse.</td></tr><tr><td><code>networked</code></td><td>Synchronized across all machines. Carries a bandwidth cost.</td></tr><tr><td><code>networked_high</code></td><td>Synchronized with higher priority.</td></tr></tbody></table><p>Timers are always networked — declaring a <code>local timer</code> is a compile-time error.</p><h3 id="scopes" tabindex="-1">Scopes <a class="header-anchor" href="#scopes" aria-label="Permalink to &quot;Scopes&quot;">​</a></h3><p>Each scope gives every instance of that kind its own copy of the variables:</p><table tabindex="0"><thead><tr><th>Scope</th><th>One copy per…</th><th>Accessed as…</th></tr></thead><tbody><tr><td><code>global</code></td><td>Match</td><td><code>my_counter</code></td></tr><tr><td><code>player</code></td><td>Player</td><td><code>current_player.is_leader</code></td></tr><tr><td><code>team</code></td><td>Team</td><td><code>current_team.goal</code></td></tr><tr><td><code>object</code></td><td>Object</td><td><code>current_object.lifetime</code></td></tr></tbody></table><h2 id="member-variables" tabindex="-1">Member variables <a class="header-anchor" href="#member-variables" aria-label="Permalink to &quot;Member variables&quot;">​</a></h2><p>Object-scoped variables (and built-in properties) are accessed with dot notation:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">action set current_player</span><span class="megalo-operator">.</span><span class="megalo-text">score add </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-text">action set current_player</span><span class="megalo-operator">.</span><span class="megalo-text">is_leader set_to </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-text">action set buy_zone</span><span class="megalo-operator">.</span><span class="megalo-text">phase_1_timer set_to haxoring_time_phase_1</span></span></code></pre></div><p>Common built-in member variables (not declared in <code>variables</code> blocks):</p><table tabindex="0"><thead><tr><th>Member</th><th>On</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>.score</code></td><td>player</td><td>number</td><td>Player&#39;s current score</td></tr><tr><td><code>.team</code></td><td>player, object</td><td>team</td><td>Owning team</td></tr><tr><td><code>.rating</code></td><td>player</td><td>number</td><td>Arena rating</td></tr><tr><td><code>.body</code></td><td>player</td><td>object</td><td>Player&#39;s physical object</td></tr><tr><td><code>.user_data</code></td><td>object</td><td>number</td><td>Forge user data field</td></tr></tbody></table><h2 id="constants" tabindex="-1">Constants <a class="header-anchor" href="#constants" aria-label="Permalink to &quot;Constants&quot;">​</a></h2><p>Constants are named numeric values declared in a <code>constants</code> block. They cannot change at runtime and incur no variable storage cost.</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">constants</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">k_special_death_type_none</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">k_special_death_type_melee</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">k_special_death_type_headshot</span><span class="megalo-text"> </span><span class="megalo-number">5</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">k_cross_map_distance</span><span class="megalo-text"> </span><span class="megalo-number">400</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>Constants are referenced by name in conditions and actions like any other numeric value:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">condition if special_death_type equal_to k_special_death_type_headshot</span></span>
<span class="line"><span class="megalo-text">action set_score add headshot_bonus player killing_player</span></span></code></pre></div><h2 id="built-in-variables" tabindex="-1">Built-in variables <a class="header-anchor" href="#built-in-variables" aria-label="Permalink to &quot;Built-in variables&quot;">​</a></h2><p>Megalo scripts can read engine state through built-in variable names that are not declared in <code>variables</code> blocks. These appear in conditions and <code>set</code> operands like ordinary identifiers.</p><p>See <a href="/MegaloEvolved/beta/docs/language/enums/built-in-variables">Built-in variables</a> for the full list with types and per-game availability.</p><p>Game options declared in <code>game_options</code> blocks also become readable constants (e.g. <code>kill_points</code>, <code>hidden_gametype</code>, <code>flag_return_time</code>).</p><p>Built-in variables can be overridden in <code>game_options</code> using <code>override</code>:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">game_options</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">score_to_win_round</span><span class="megalo-text"> </span><span class="megalo-number">25</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">round_count</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">round_time_limit</span><span class="megalo-text"> </span><span class="megalo-number">10</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>See <a href="/MegaloEvolved/beta/docs/language/enums/built-in-variables">Built-in variables</a> and <a href="/MegaloEvolved/beta/docs/language/enums/game-options">Game options</a> for the full lists.</p><h2 id="temporary-variables" tabindex="-1">Temporary variables <a class="header-anchor" href="#temporary-variables" aria-label="Permalink to &quot;Temporary variables&quot;">​</a></h2><p>Temporary variables are declared inside an <a href="/MegaloEvolved/beta/docs/language/elements/trigger#action-scope">action scope</a> — a trigger body, <code>for_each</code> sub-block, or <a href="/MegaloEvolved/beta/docs/language/elements/begin"><code>begin</code></a> sub-block — and exist only for the duration of that scope:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-type">player</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">player_died</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-text"> </span><span class="megalo-enumMember">enemy</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">temporary </span><span class="megalo-type">player</span><span class="megalo-text"> </span><span class="megalo-variable">killer</span><span class="megalo-text"> </span><span class="megalo-variable">none</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">player_death_get_killing_player</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-text"> </span><span class="megalo-variable">killer</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">set</span><span class="megalo-text"> </span><span class="megalo-variable">killer</span><span class="megalo-operator">.</span><span class="megalo-property">score</span><span class="megalo-text"> </span><span class="megalo-keyword">add</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>Syntax: <code>temporary &lt;type&gt; &lt;name&gt; &lt;initial_value&gt;</code></p><p>Valid types are <code>number</code>, <code>object</code>, <code>team</code>, and <code>player</code>. There is no <code>timer</code> temporary.</p><p>Temporaries are useful for storing getter action results or intermediate values without declaring a permanent <a href="#custom-variables"><code>variables</code></a> slot. Each <code>temporary</code> line also counts as one <strong>action</strong> toward the script&#39;s 1024-action limit, because the compiler emits an internal <code>set</code> for the initial value.</p><p>Temporary pool sizes and overflow caps depend on the megalo version. See <strong>Limits</strong> on the <a href="/MegaloEvolved/beta/docs/versions/">version pages</a> — <a href="/MegaloEvolved/beta/docs/versions/107-mcc/#limits">107 (MCC)</a> uses dedicated temporary pools per <a href="/MegaloEvolved/beta/docs/language/elements/trigger#action-scope">action scope</a>; Xbox 360 builds such as <a href="/MegaloEvolved/beta/docs/versions/107/#limits">107</a> map temporaries directly to globals. Overflow behavior is controlled by <a href="/MegaloEvolved/beta/docs/language/compiler-settings#temporary-variable-overflow">Compiler settings — Temporary variable overflow</a>.</p><h2 id="special-literals" tabindex="-1">Special literals <a class="header-anchor" href="#special-literals" aria-label="Permalink to &quot;Special literals&quot;">​</a></h2><p>Three special built-in values appear throughout Megalo:</p><table tabindex="0"><thead><tr><th>Literal</th><th>Meaning</th></tr></thead><tbody><tr><td><code>true</code></td><td>Boolean true (evaluates as 1)</td></tr><tr><td><code>false</code></td><td>Boolean false (evaluates as 0)</td></tr><tr><td><code>none</code></td><td>Null / empty reference for objects, players, teams</td></tr></tbody></table><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-text">condition if current_team</span><span class="megalo-operator">.</span><span class="megalo-text">flag equal_to none</span></span>
<span class="line"><span class="megalo-text">action set current_player</span><span class="megalo-operator">.</span><span class="megalo-text">body </span><span class="megalo-operator">=</span><span class="megalo-text"> my_body</span></span></code></pre></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/language/elements/variables">Elements — variables</a> and <a href="/MegaloEvolved/beta/docs/language/elements/constants">constants</a></li><li><a href="/MegaloEvolved/beta/docs/language/references">References</a> — how variables appear as operands</li><li><a href="/MegaloEvolved/beta/docs/language/elements/trigger/action">action</a> — the <code>set</code> action and <a href="/MegaloEvolved/beta/docs/language/enums/math-operations">Math operations</a></li><li><a href="/MegaloEvolved/beta/docs/language/elements/trigger">trigger</a> — <code>temporary</code> variables inside triggers</li><li><a href="/MegaloEvolved/beta/docs/versions/">Megalo versions</a> — compile-time limits by encoding version</li></ul>`,52)])])}const b=e(n,[["render",o]]);export{g as __pageData,b as default};
